WITH valid AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, LOWER(txn_type) AS txn_type_lower FROM transactions WHERE txn_time > TIMESTAMP '2023-11-20 23:00:00' AND merchant IS NOT NULL AND amount > 2100) SELECT * FROM (SELECT account_id, merchant, amount FROM valid) src PIVOT (MAX(amount) FOR merchant IN ('Grab' AS grab, 'Shell' AS shell, '7-Eleven' AS v_7_eleven));
